204		"google.golang.org/grpc/status"
205	)
206	
207	// reservedCIDRs lists IP ranges that must never be targeted by outbound webhook requests.
208	// Covers loopback, RFC-1918 private, link-local (including cloud IMDS at 169.254.169.254),
209	// and their IPv6 equivalents.
210	var reservedCIDRs = []string{
211		"127.0.0.0/8",    // IPv4 loopback
212		"10.0.0.0/8",     // RFC-1918 class A
213		"172.16.0.0/12",  // RFC-1918 class B
214		"192.168.0.0/16", // RFC-1918 class C
215		"169.254.0.0/16", // Link-local / cloud IMDS
216		"::1/128",        // IPv6 loopback
217		"fc00::/7",       // IPv6 unique local
218		"fe80::/10",      // IPv6 link-local
219	}
220	
221	// reservedNetworks is the parsed form of reservedCIDRs, built once at startup.
222	var reservedNetworks []*net.IPNet
223	
224	func init() {
225		for _, cidr := range reservedCIDRs {
226			_, network, err := net.ParseCIDR(cidr)
227			if err != nil {
228				panic("webhook: invalid reserved CIDR " + cidr + ": " + err.Error())
229			}
230			reservedNetworks = append(reservedNetworks, network)
231		}
232	}
233	
234	// AllowPrivateIPs controls whether webhook URLs may resolve to reserved/private
235	// IP addresses. When true, the SSRF protection is disabled. This is useful for
236	// self-hosted deployments where webhooks target services on the local network.
237	var AllowPrivateIPs bool
238	
239	// isReservedIP reports whether ip falls within any reserved/private range.
240	func isReservedIP(ip net.IP) bool {
241		if AllowPrivateIPs {
242			return false
243		}
244		for _, network := range reservedNetworks {
245			if network.Contains(ip) {
246				return true
247			}
248		}
249		return false
250	}
251	
252	// ValidateURL checks that rawURL:
253	//  1. Parses as a valid absolute URL.
254	//  2. Uses the http or https scheme.
255	//  3. Does not resolve to a reserved/private IP address.
256	//
257	// It returns a gRPC InvalidArgument status error so callers can return it directly.
258	func ValidateURL(rawURL string) error {
259		u, err := url.ParseRequestURI(rawURL)
260		if err != nil {
261			return status.Errorf(codes.InvalidArgument, "invalid webhook URL: %v", err)
262		}
263		if u.Scheme != "http" && u.Scheme != "https" {
264			return status.Errorf(codes.InvalidArgument, "webhook URL must use http or https scheme, got %q", u.Scheme)
265		}
266	
267		ips, err := net.LookupHost(u.Hostname())
268		if err != nil {
269			return status.Errorf(codes.InvalidArgument, "webhook URL hostname could not be resolved: %v", err)
270		}
271	
272		for _, ipStr := range ips {
273			ip := net.ParseIP(ipStr)
274			if ip != nil && isReservedIP(ip) {
275				return status.Errorf(codes.InvalidArgument, "webhook URL must not resolve to a reserved or private IP address")
276			}
277		}
278		return nil
279	}
280	
281	// ValidateSigningSecret checks that secret is either empty (allowed) or contains
282	// only printable ASCII characters (0x20–0x7E), excluding all control characters
283	// such as \r and \n, which would corrupt the webhook signature headers. When the
284	// secret uses the Standard Webhooks "whsec_<base64>" serialization, the base64
285	// body must decode cleanly so signing cannot silently fall back to the wrong key.
286	func ValidateSigningSecret(secret string) error {
287		if secret == "" {
288			return nil
289		}
290		for _, r := range secret {
291			if r < 0x20 || r > 0x7E {
292				return status.Errorf(codes.InvalidArgument, "signing secret contains invalid character")
293			}
294		}
295		if _, err := resolveSigningKey(secret); err != nil {
296			return status.Errorf(codes.InvalidArgument, "%v", err)
297		}
298		return nil
299	}

